import * as zod from "zod";

export const groundingIndicatorSourcesCitedMin = 0;

export const groundingIndicatorClaimSpansMin = 0;

export const groundingIndicatorUncitedSpansMin = 0;

export const groundingIndicatorUncitedItemStartMin = 0;

export const groundingIndicatorUncitedMax = 64;

export const groundingIndicatorInvalidMarkersMin = 0;

export const GroundingIndicator = zod
  .object({
    version: zod.literal(1),
    sources_available: zod
      .int()
      .min(1)
      .describe(
        "The tool results the model saw, numbered 1, 2, 3 in request order.",
      ),
    sources_cited: zod
      .int()
      .min(groundingIndicatorSourcesCitedMin)
      .describe(
        "The distinct sources the answer cites with a valid `[n]` marker.",
      ),
    claim_spans: zod
      .int()
      .min(groundingIndicatorClaimSpansMin)
      .describe(
        "The statements of the answer: sentences outside code blocks, headings and tables that are not questions or lead-ins ending with a colon.",
      ),
    uncited_spans: zod
      .int()
      .min(groundingIndicatorUncitedSpansMin)
      .describe("The statements without a valid citation marker."),
    uncited: zod
      .array(
        zod.object({
          start: zod.int().min(groundingIndicatorUncitedItemStartMin),
          end: zod.int().min(1),
        }),
      )
      .max(groundingIndicatorUncitedMax)
      .describe(
        "The first 64 statements without a citation, in answer order, as UTF-16 code unit offsets into the stored answer text.",
      ),
    invalid_markers: zod
      .int()
      .min(groundingIndicatorInvalidMarkersMin)
      .describe("Markers whose number names no source."),
  })
  .describe(
    "On an agent's answer (ADR-0043 decision 5): how many sources the answer cites and which statements have no citation. Present only when the agent's version sets `meta.citations` to `required` and the model saw at least one tool result; absent, not zero, otherwise. There is no confidence score. A cited source does not prove that the source supports the statement. Main stores the worker's value after it checks the shape (internal/infra/db/repos/agent_grounding.go).",
  );

export type GroundingIndicator = zod.input<typeof GroundingIndicator>;
export type GroundingIndicatorOutput = zod.output<typeof GroundingIndicator>;
